begin;

-- Persist the 111 explicitly reviewed supplemental resource decisions. The 130
-- malformed promoted source-location rows remain untouched as provenance. This
-- migration adds eight reviewed addresses, five of which are exact public-site
-- candidates awaiting genuine geocoding. It asserts no coordinates.
--
-- Decision payload SHA-256: e6995086700562703bb65f50f831c6a251b54ea635e1c6bb705dc5e104ba9433
-- Source snapshot SHA-256: a33bc88db0f99648409185f8401c355a0640e919e0256eeac0dacea0060bb1b7

create temporary table tmp_v3_13_manual_location_decisions on commit drop as
select
  (item->>'resource_entity_id')::uuid as resource_entity_id,
  array(
    select value::uuid
    from jsonb_array_elements_text(item->'malformed_location_ids')
  ) as malformed_location_ids,
  item->>'state' as jurisdiction_state,
  item->>'resource_name' as resource_name,
  item->>'disposition' as disposition,
  nullif(item->'reviewed_address', 'null'::jsonb) as reviewed_address,
  item->>'location_kind' as location_kind,
  (item->>'map_eligible')::boolean as map_eligible,
  item->>'source_type' as source_type,
  item->>'source_reference' as source_reference,
  item->>'review_note' as review_note,
  ordinality::integer as review_ordinality
from jsonb_array_elements(
  (convert_from(decode(concat(
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  ''
), 'base64'), 'UTF8')::jsonb)->'decisions'
) with ordinality as source(item, ordinality);

create unique index tmp_v3_13_manual_location_decisions_resource_idx
  on tmp_v3_13_manual_location_decisions (resource_entity_id);

create temporary table tmp_v3_13_expected_malformed_locations
on commit drop as
select
  (item->>'location_id')::uuid as location_id,
  (item->>'resource_entity_id')::uuid as resource_entity_id,
  item->>'address_line1' as address_line1,
  item->>'source_pk' as source_pk
from jsonb_array_elements(convert_from(decode(concat(
  '',
  '',
  '',
  '',
  ''
), 'base64'), 'UTF8')::jsonb) source(item);

create unique index tmp_v3_13_expected_malformed_locations_idx
  on tmp_v3_13_expected_malformed_locations (location_id);

create temporary table tmp_v3_13_manual_location_decision_ids
on commit drop as
select
  d.resource_entity_id,
  malformed_location_id
from tmp_v3_13_manual_location_decisions d
cross join lateral unnest(d.malformed_location_ids)
  malformed(malformed_location_id);

create unique index tmp_v3_13_manual_location_decision_ids_idx
  on tmp_v3_13_manual_location_decision_ids (malformed_location_id);

create temporary table tmp_v3_13_manual_location_normalized
on commit drop as
with address_text as (
  select
    d.*,
    case jsonb_typeof(d.reviewed_address)
      when 'string' then d.reviewed_address #>> '{}'
      when 'object' then concat_ws(
        ', ',
        nullif(d.reviewed_address->>'address_line1', ''),
        nullif(d.reviewed_address->>'address_line2', ''),
        nullif(d.reviewed_address->>'city', ''),
        nullif(concat_ws(
          ' ',
          nullif(d.reviewed_address->>'state', ''),
          nullif(d.reviewed_address->>'postal_code', '')
        ), '')
      )
      else null
    end as reviewed_address_text
  from tmp_v3_13_manual_location_decisions d
)
select
  a.*,
  case
    when jsonb_typeof(a.reviewed_address) = 'object'
      then nullif(a.reviewed_address->>'address_line1', '')
    else a.reviewed_address_text
  end as address_line1,
  case
    when jsonb_typeof(a.reviewed_address) = 'object'
      then nullif(a.reviewed_address->>'address_line2', '')
    else null
  end as address_line2,
  case
    when jsonb_typeof(a.reviewed_address) = 'object'
      then nullif(a.reviewed_address->>'city', '')
    else null
  end as city,
  coalesce(
    case
      when jsonb_typeof(a.reviewed_address) = 'object'
        then nullif(a.reviewed_address->>'state', '')
      else null
    end,
    substring(
      a.reviewed_address_text
      from '([A-Z]{2})[ ,]+[0-9]{5}(-[0-9]{4})?\s*$'
    ),
    substring(a.reviewed_address_text from ',\s*([A-Z]{2})\s*$'),
    a.jurisdiction_state
  ) as location_state,
  coalesce(
    case
      when jsonb_typeof(a.reviewed_address) = 'object'
        then nullif(a.reviewed_address->>'postal_code', '')
      else null
    end,
    substring(
      a.reviewed_address_text
      from '([0-9]{5}(-[0-9]{4})?)\s*$'
    )
  ) as postal_code,
  coalesce(
    case
      when jsonb_typeof(a.reviewed_address) = 'object'
        then nullif(a.reviewed_address->>'country', '')
      else null
    end,
    'US'
  ) as country
from address_text a;

do $guard$
declare
  decision_count integer;
  unique_resource_count integer;
  malformed_id_count integer;
  expected_source_count integer;
  physical_count integer;
  mailing_count integer;
  administrative_count integer;
  jurisdiction_count integer;
  network_count integer;
  national_count integer;
  map_eligible_count integer;
  addressed_count integer;
  missing_entities integer;
  entity_lineage_drift integer;
  prior_review_overlap integer;
  missing_source_locations integer;
  source_location_drift integer;
  source_location_coordinate_drift integer;
  live_source_count bigint;
begin
  select count(*), count(distinct resource_entity_id)
    into decision_count, unique_resource_count
  from tmp_v3_13_manual_location_decisions;

  select count(*) into malformed_id_count
  from tmp_v3_13_manual_location_decision_ids;

  select count(*) into expected_source_count
  from tmp_v3_13_expected_malformed_locations;

  select
    count(*) filter (where disposition = 'replace_with_physical'),
    count(*) filter (where disposition = 'replace_with_mailing'),
    count(*) filter (where disposition = 'replace_with_administrative'),
    count(*) filter (where disposition = 'jurisdiction_only'),
    count(*) filter (where disposition = 'multi_location_network'),
    count(*) filter (where disposition = 'national_coverage_alias'),
    count(*) filter (where map_eligible),
    count(*) filter (where reviewed_address is not null)
  into
    physical_count,
    mailing_count,
    administrative_count,
    jurisdiction_count,
    network_count,
    national_count,
    map_eligible_count,
    addressed_count
  from tmp_v3_13_manual_location_decisions;

  select count(*) into missing_entities
  from tmp_v3_13_manual_location_decisions d
  left join public.luminari_resource_entities e
    on e.resource_entity_id = d.resource_entity_id
  where e.resource_entity_id is null;

  select count(*) into entity_lineage_drift
  from tmp_v3_13_manual_location_decisions d
  join public.luminari_resource_entities e
    on e.resource_entity_id = d.resource_entity_id
  where e.state is distinct from d.jurisdiction_state
     or e.source_table is distinct from 'state_directory_logical_record';

  select count(*) into prior_review_overlap
  from tmp_v3_13_manual_location_decisions d
  join public.luminari_resource_location_resolutions r
    on r.resource_entity_id = d.resource_entity_id
   and r.review_version = 'v3_13_manual_location_reconciliation_v1';

  select count(*) into missing_source_locations
  from tmp_v3_13_expected_malformed_locations x
  left join public.luminari_resource_locations l
    on l.location_id = x.location_id
  where l.location_id is null;

  select count(*) into source_location_drift
  from tmp_v3_13_expected_malformed_locations x
  join public.luminari_resource_locations l
    on l.location_id = x.location_id
  where l.resource_entity_id is distinct from x.resource_entity_id
     or l.address_line1 is distinct from x.address_line1
     or l.source_pk is distinct from x.source_pk
     or l.source_table is distinct from 'state_directory_logical_record';

  select count(*) into source_location_coordinate_drift
  from tmp_v3_13_expected_malformed_locations x
  join public.luminari_resource_locations l
    on l.location_id = x.location_id
  where l.latitude is not null or l.longitude is not null;

  select count(*) into live_source_count
  from public.luminari_resource_entities
  where source_table = 'state_directory_logical_record';

  if decision_count <> 111 or unique_resource_count <> 111 then
    raise exception
      'supplemental decision drift: expected 111/111, found %/%',
      decision_count, unique_resource_count;
  end if;

  if malformed_id_count <> 130 or expected_source_count <> 130 then
    raise exception
      'supplemental source ID drift: expected 130/130, found %/%',
      malformed_id_count, expected_source_count;
  end if;

  if physical_count <> 5
     or mailing_count <> 1
     or administrative_count <> 2
     or jurisdiction_count <> 86
     or network_count <> 17
     or national_count <> 0
     or map_eligible_count <> 5
     or addressed_count <> 8 then
    raise exception
      'supplemental disposition drift: physical %, mailing %, administrative %, jurisdiction %, network %, national %, map %, addressed %',
      physical_count, mailing_count, administrative_count, jurisdiction_count,
      network_count, national_count, map_eligible_count, addressed_count;
  end if;

  if exists (
    select 1
    from tmp_v3_13_manual_location_decisions
    where map_eligible is distinct from
      (disposition = 'replace_with_physical')
       or (reviewed_address is not null) is distinct from
      (disposition in (
        'replace_with_physical',
        'replace_with_mailing',
        'replace_with_administrative'
      ))
       or cardinality(malformed_location_ids) < 1
       or nullif(btrim(location_kind), '') is null
       or nullif(btrim(source_type), '') is null
       or nullif(btrim(source_reference), '') is null
       or nullif(btrim(review_note), '') is null
  ) then
    raise exception 'supplemental decision semantic guard failed';
  end if;

  if exists (
    select 1
    from tmp_v3_13_manual_location_decisions d
    join tmp_v3_13_manual_location_decision_ids i using (resource_entity_id)
    join tmp_v3_13_expected_malformed_locations x
      on x.location_id = i.malformed_location_id
    where x.resource_entity_id is distinct from d.resource_entity_id
  ) then
    raise exception 'supplemental decision/source ownership guard failed';
  end if;

  -- Enforce the reviewed live snapshot whenever any v3.13 corpus entities are
  -- present. A fresh schema replay intentionally has none and must write none.
  if live_source_count > 0 and (
     missing_entities <> 0
     or entity_lineage_drift <> 0
     or prior_review_overlap <> 0
     or missing_source_locations <> 0
     or source_location_drift <> 0
     or source_location_coordinate_drift <> 0) then
    raise exception
      'supplemental live-source drift: missing entities %, lineage %, prior overlap %, missing locations %, location %, coordinate %',
      missing_entities, entity_lineage_drift, prior_review_overlap,
      missing_source_locations, source_location_drift,
      source_location_coordinate_drift;
  end if;

  raise notice
    'v3.13 supplemental hand-review guard passed (decision sha256 e6995086700562703bb65f50f831c6a251b54ea635e1c6bb705dc5e104ba9433; source sha256 a33bc88db0f99648409185f8401c355a0640e919e0256eeac0dacea0060bb1b7)';
end
$guard$;

do $prerequisite$
begin
  if to_regclass('public.luminari_resource_location_resolutions') is null then
    raise exception
      'required table public.luminari_resource_location_resolutions is missing';
  end if;
end
$prerequisite$;

alter table public.luminari_resource_location_resolutions
  enable row level security;

revoke all on table public.luminari_resource_location_resolutions
  from anon, authenticated;

grant select, insert, update, delete
  on table public.luminari_resource_location_resolutions
  to service_role;

insert into public.luminari_resource_location_resolutions (
  resolution_id,
  resource_entity_id,
  review_version,
  jurisdiction_state,
  resource_name,
  live_resource_name_at_review,
  disposition,
  reviewed_address,
  location_kind,
  map_eligible,
  source_type,
  source_reference,
  review_note,
  malformed_location_ids,
  metadata,
  reviewed_at,
  updated_at
)
select
  public.luminari_stable_uuid_v1(
    'v3_13_manual_location_reconciliation_v2|resolution|' || d.resource_entity_id::text
  ),
  d.resource_entity_id,
  'v3_13_manual_location_reconciliation_v2',
  d.jurisdiction_state,
  d.resource_name,
  e.resource_name,
  d.disposition,
  d.reviewed_address,
  d.location_kind,
  d.map_eligible,
  d.source_type,
  d.source_reference,
  d.review_note,
  d.malformed_location_ids,
  jsonb_build_object(
    'review_method', 'record-by-record manual review',
    'decision_ordinality', d.review_ordinality,
    'decision_payload_sha256', 'e6995086700562703bb65f50f831c6a251b54ea635e1c6bb705dc5e104ba9433',
    'source_snapshot_sha256', 'a33bc88db0f99648409185f8401c355a0640e919e0256eeac0dacea0060bb1b7',
    'source_rows_preserved', true,
    'authoritative_for_circulation', true,
    'coordinates_asserted', false,
    'review_sequence', 2
  ),
  now(),
  now()
from tmp_v3_13_manual_location_decisions d
join public.luminari_resource_entities e
  on e.resource_entity_id = d.resource_entity_id
on conflict (resolution_id) do update set
  jurisdiction_state = excluded.jurisdiction_state,
  resource_name = excluded.resource_name,
  live_resource_name_at_review = excluded.live_resource_name_at_review,
  disposition = excluded.disposition,
  reviewed_address = excluded.reviewed_address,
  location_kind = excluded.location_kind,
  map_eligible = excluded.map_eligible,
  source_type = excluded.source_type,
  source_reference = excluded.source_reference,
  review_note = excluded.review_note,
  malformed_location_ids = excluded.malformed_location_ids,
  metadata = excluded.metadata,
  updated_at = now();

insert into public.luminari_resource_locations (
  location_id,
  resource_entity_id,
  address_line1,
  address_line2,
  city,
  state,
  postal_code,
  country,
  latitude,
  longitude,
  coordinate_quality,
  geocode_source,
  source_table,
  source_pk,
  metadata,
  created_at
)
select
  public.luminari_stable_uuid_v1(
    'v3_13_manual_location_reconciliation_v2|location|' || d.resource_entity_id::text
  ),
  d.resource_entity_id,
  d.address_line1,
  d.address_line2,
  d.city,
  d.location_state,
  d.postal_code,
  d.country,
  null,
  null,
  case d.disposition
    when 'replace_with_physical' then 'manual_reviewed_exact_ungeocoded'
    when 'replace_with_mailing' then 'manual_reviewed_mailing'
    when 'replace_with_administrative' then 'manual_reviewed_administrative'
  end,
  null,
  'luminari_resource_location_resolutions',
  public.luminari_stable_uuid_v1(
    'v3_13_manual_location_reconciliation_v2|resolution|' || d.resource_entity_id::text
  )::text,
  jsonb_build_object(
    'review_version', 'v3_13_manual_location_reconciliation_v2',
    'disposition', d.disposition,
    'location_kind', d.location_kind,
    'map_eligible', d.map_eligible,
    'source_type', d.source_type,
    'source_reference', d.source_reference,
    'review_note', d.review_note,
    'reviewed_address', d.reviewed_address,
    'malformed_location_ids', to_jsonb(d.malformed_location_ids),
    'source_rows_preserved', true,
    'coordinates_asserted', false,
    'geocode_status', case
      when d.map_eligible then 'manual_reviewed_pending'
      else 'not_applicable'
    end
  ),
  now()
from tmp_v3_13_manual_location_normalized d
join public.luminari_resource_entities e
  on e.resource_entity_id = d.resource_entity_id
where d.reviewed_address is not null
on conflict (location_id) do update set
  address_line1 = excluded.address_line1,
  address_line2 = excluded.address_line2,
  city = excluded.city,
  state = excluded.state,
  postal_code = excluded.postal_code,
  country = excluded.country,
  latitude = null,
  longitude = null,
  coordinate_quality = excluded.coordinate_quality,
  geocode_source = null,
  metadata = excluded.metadata
where public.luminari_resource_locations.source_table =
    'luminari_resource_location_resolutions'
  and public.luminari_resource_locations.source_pk = excluded.source_pk;

create or replace view
  public.v_luminari_resource_locations_current_v3_13
with (security_invoker = true)
as
with ranked_resolution as (
  select
    r.*,
    row_number() over (
      partition by r.resource_entity_id
      order by
        case
          when r.review_version ~
            '^v3_13_manual_location_reconciliation_v[0-9]+$'
          then substring(r.review_version from '_v([0-9]+)$')::integer
          else -1
        end desc,
        r.updated_at desc,
        r.resolution_id desc
    ) as review_rank
  from public.luminari_resource_location_resolutions r
),
current_resolution as (
  select *
  from ranked_resolution
  where review_rank = 1
)
select
  l.*,
  r.disposition as manual_disposition,
  r.location_kind as manual_location_kind,
  r.map_eligible as manual_map_eligible,
  r.source_reference as manual_source_reference,
  r.review_note as manual_review_note,
  r.review_version as manual_review_version
from public.luminari_resource_locations l
left join current_resolution r
  on r.resource_entity_id = l.resource_entity_id
where (
    r.resource_entity_id is null
    or (
      l.source_table = 'luminari_resource_location_resolutions'
      and l.source_pk = r.resolution_id::text
    )
  );

comment on view
  public.v_luminari_resource_locations_current_v3_13 is
  'Current v3.13 location circulation view. For 557 hand-reviewed resources, all superseded promoted location rows remain preserved but hidden; reviewed addresses circulate with truthful location kinds, and coverage/network dispositions expose no fake point.';

do $acceptance$
declare
  v2_resolution_count integer;
  v2_resource_count integer;
  v2_location_count integer;
  v2_location_resource_count integer;
  v2_exact_pending_count integer;
  combined_resolution_count integer;
  combined_resource_count integer;
  combined_location_count integer;
  combined_exact_pending_count integer;
  combined_legacy_preserved integer;
  accidental_coordinate_count integer;
  leaked_legacy_count integer;
  addressed_without_current integer;
  nonpoint_with_current integer;
  uncovered_corpus_resources integer;
  live_source_count bigint;
begin
  select count(*) into live_source_count
  from public.luminari_resource_entities
  where source_table = 'state_directory_logical_record';

  select count(*), count(distinct resource_entity_id)
    into v2_resolution_count, v2_resource_count
  from public.luminari_resource_location_resolutions
  where review_version = 'v3_13_manual_location_reconciliation_v2';

  select count(*), count(distinct resource_entity_id)
    into v2_location_count, v2_location_resource_count
  from public.luminari_resource_locations
  where source_table = 'luminari_resource_location_resolutions'
    and metadata->>'review_version' = 'v3_13_manual_location_reconciliation_v2';

  select count(*) into v2_exact_pending_count
  from public.luminari_resource_locations
  where source_table = 'luminari_resource_location_resolutions'
    and metadata->>'review_version' = 'v3_13_manual_location_reconciliation_v2'
    and coordinate_quality = 'manual_reviewed_exact_ungeocoded';

  select count(*), count(distinct resource_entity_id)
    into combined_resolution_count, combined_resource_count
  from public.luminari_resource_location_resolutions
  where review_version in ('v3_13_manual_location_reconciliation_v1', 'v3_13_manual_location_reconciliation_v2');

  select count(*) into combined_location_count
  from public.luminari_resource_locations
  where source_table = 'luminari_resource_location_resolutions'
    and metadata->>'review_version'
      in ('v3_13_manual_location_reconciliation_v1', 'v3_13_manual_location_reconciliation_v2');

  select count(*) into combined_exact_pending_count
  from public.luminari_resource_locations
  where source_table = 'luminari_resource_location_resolutions'
    and metadata->>'review_version'
      in ('v3_13_manual_location_reconciliation_v1', 'v3_13_manual_location_reconciliation_v2')
    and coordinate_quality = 'manual_reviewed_exact_ungeocoded';

  select count(*) into combined_legacy_preserved
  from public.luminari_resource_location_resolutions r
  cross join lateral unnest(r.malformed_location_ids) source_location_id
  join public.luminari_resource_locations l
    on l.location_id = source_location_id
  where r.review_version
    in ('v3_13_manual_location_reconciliation_v1', 'v3_13_manual_location_reconciliation_v2');

  select count(*) into accidental_coordinate_count
  from public.luminari_resource_locations
  where source_table = 'luminari_resource_location_resolutions'
    and metadata->>'review_version'
      in ('v3_13_manual_location_reconciliation_v1', 'v3_13_manual_location_reconciliation_v2')
    and (latitude is not null or longitude is not null);

  select count(*) into leaked_legacy_count
  from public.v_luminari_resource_locations_current_v3_13 v
  join public.luminari_resource_location_resolutions r
    on r.resource_entity_id = v.resource_entity_id
   and r.review_version
     in ('v3_13_manual_location_reconciliation_v1', 'v3_13_manual_location_reconciliation_v2')
  where v.source_table <> 'luminari_resource_location_resolutions'
     or v.source_pk <> r.resolution_id::text;

  select count(*) into addressed_without_current
  from public.luminari_resource_location_resolutions r
  where r.review_version
      in ('v3_13_manual_location_reconciliation_v1', 'v3_13_manual_location_reconciliation_v2')
    and r.reviewed_address is not null
    and not exists (
      select 1
      from public.v_luminari_resource_locations_current_v3_13 v
      where v.resource_entity_id = r.resource_entity_id
    );

  select count(*) into nonpoint_with_current
  from public.luminari_resource_location_resolutions r
  join public.v_luminari_resource_locations_current_v3_13 v
    using (resource_entity_id)
  where r.review_version
      in ('v3_13_manual_location_reconciliation_v1', 'v3_13_manual_location_reconciliation_v2')
    and r.reviewed_address is null;

  select count(*) into uncovered_corpus_resources
  from public.luminari_resource_entities e
  where e.source_table = 'state_directory_logical_record'
    and not exists (
      select 1
      from public.v_luminari_resource_locations_current_v3_13 v
      where v.resource_entity_id = e.resource_entity_id
    )
    and not exists (
      select 1
      from public.luminari_resource_location_resolutions r
      where r.resource_entity_id = e.resource_entity_id
        and r.review_version
          in ('v3_13_manual_location_reconciliation_v1', 'v3_13_manual_location_reconciliation_v2')
    );

  if live_source_count > 0
     and (v2_resolution_count <> 111 or v2_resource_count <> 111) then
    raise exception
      'v2 resolution write drift: expected 111/111, found %/%',
      v2_resolution_count, v2_resource_count;
  end if;

  if live_source_count > 0 and (
     v2_location_count <> 8
     or v2_location_resource_count <> 8
     or v2_exact_pending_count <> 5) then
    raise exception
      'v2 reviewed-location drift: expected 8/8/5, found %/%/%',
      v2_location_count, v2_location_resource_count,
      v2_exact_pending_count;
  end if;

  if live_source_count > 0 and (
     combined_resolution_count <> 557
     or combined_resource_count <> 557
     or combined_location_count <> 217
     or combined_exact_pending_count <> 115
     or combined_legacy_preserved <> 578) then
    raise exception
      'combined review drift: resolutions %/%, locations %, exact %, preserved %',
      combined_resolution_count, combined_resource_count,
      combined_location_count, combined_exact_pending_count,
      combined_legacy_preserved;
  end if;

  if accidental_coordinate_count <> 0
     or leaked_legacy_count <> 0
     or addressed_without_current <> 0
     or nonpoint_with_current <> 0
     or uncovered_corpus_resources <> 0 then
    raise exception
      'combined circulation acceptance failed: coordinates %, leaked %, addressed missing %, nonpoint rows %, uncovered corpus %',
      accidental_coordinate_count, leaked_legacy_count,
      addressed_without_current, nonpoint_with_current,
      uncovered_corpus_resources;
  end if;

  if live_source_count = 0
     and (v2_resolution_count <> 0
       or v2_resource_count <> 0
       or v2_location_count <> 0
       or v2_location_resource_count <> 0
       or v2_exact_pending_count <> 0
       or combined_resolution_count <> 0
       or combined_resource_count <> 0
       or combined_location_count <> 0
       or combined_exact_pending_count <> 0
       or combined_legacy_preserved <> 0) then
    raise exception
      'supplemental reconciliation wrote rows without a live source corpus';
  end if;
end
$acceptance$;

commit;
